var inputPath = Argument["input"];
var outputPath = Argument["output"];
builder.OpenFile("jsValue(inputPath)");
var oDocument = Api.GetDocument();
var oPage = oDocument.GetPage(0);
var oShape = Api.CreateShape("rect", 3200000, 500000, Api.CreateNoFill(), Api.CreateStroke(0, Api.CreateNoFill()));
var oParagraph = oShape.GetContent().GetElement(0);
oParagraph.AddText("NHO_RUNTIME_PDF_EDITED");
oShape.SetPosition(500000, 500000);
oPage.AddObject(oShape);
builder.SaveFile("pdf", "jsValue(outputPath)");
builder.CloseFile();
